INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('6db2798e-686c-4bd3-8c63-22c2beff1002','9','hidrosfera','published',1,261,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('6db2798e-686c-4bd3-8c63-22c2beff1002','ro','Pe hartă vezi două întinderi de apă sărată: una foarte mare, mărginită de continente, cealaltă mult mai mică, situată la marginea unui continent și legată de prima. Cum le numim?','["Prima este o mare, a doua un ocean.","Prima este un ocean, a doua o mare.","Amândouă sunt oceane, doar de mărimi diferite.","Amândouă sunt mări, doar de mărimi diferite."]','Oceanul este o întindere foarte mare de apă sărată ce înconjoară continentele; marea este mult mai mică, situată între sau la marginea continentelor și legată de ocean.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('30f1745a-6c0c-4665-b2da-6490c3720fcd','9','hidrosfera','published',1,262,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('30f1745a-6c0c-4665-b2da-6490c3720fcd','ro','Groapa Marianelor, cel mai adânc punct de pe Terra (circa −11.022 m), se află în Oceanul Pacific. De ce tocmai acest ocean deține recordul de adâncime?','["Pentru că este cel mai mic dintre oceane.","Pentru că este cel mai mare și mai adânc dintre cele patru oceane.","Pentru că este cel mai sărat dintre oceane.","Pentru că este singurul ocean înghețat la suprafață."]','Pacificul este atât cel mai întins, cât și cel mai adânc ocean; de aceea aici se află și cel mai adânc punct al planetei, Groapa Marianelor.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('ba0a125a-1d29-4d18-820c-9fa6722e5a5d','9','hidrosfera','published',0,263,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('ba0a125a-1d29-4d18-820c-9fa6722e5a5d','ro','Marea Neagră este aproape complet înconjurată de uscat și comunică cu Oceanul Planetar doar printr-o strâmtoare îngustă. Ce tip de mare este?','["Mare interioară (continentală).","Mare deschisă.","Mare interinsulară.","Mare mărginașă."]','Mările interioare (continentale) sunt adânc pătrunse în uscat, ca Marea Neagră; se deosebesc de mările deschise, larg legate de ocean, sau de cele mărginașe, doar parțial separate de ocean prin peninsule și arhipelaguri.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('80120c73-9124-464e-ab92-c36db5a420c9','9','hidrosfera','published',1,264,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('80120c73-9124-464e-ab92-c36db5a420c9','ro','Marea Mediterană se află între trei continente (Europa, Africa, Asia) și leagă mai multe țărmuri diferite. Cum se clasifică ea după poziție?','["Mare interinsulară.","Mare mediterană (intercontinentală).","Mare mărginașă.","Mare interioară."]','Mările mediterane (intercontinentale) se află între continente, exact poziția Mării Mediterane — de altfel numele tipului vine chiar de la ea.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('10d78656-e92f-403a-9fbb-0829ef5b13fb','9','hidrosfera','published',1,265,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('10d78656-e92f-403a-9fbb-0829ef5b13fb','ro','Salinitatea este de doar 5–6‰ în Marea Baltică, dar ajunge la 41‰ în Marea Roșie. Ce explică această diferență uriașă?','["Marea Baltică este mult mai adâncă decât Marea Roșie.","În Marea Baltică se varsă multe râuri și evaporația este slabă, pe când Marea Roșie e într-o zonă caldă, secetoasă și închisă, cu evaporație puternică.","Marea Roșie conține alge care produc sare.","Marea Baltică este înghețată tot anul."]','Salinitatea depinde de raportul dintre evaporație și aportul de apă dulce. Baltica primește mulți afluenți și evaporă puțin (apă diluată); Marea Roșie, caldă și închisă, evaporă mult și primește puțină apă dulce, așa că sărurile se concentrează.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('49844014-bf0f-4995-bbcf-38b5fcd72479','9','hidrosfera','published',0,266,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('49844014-bf0f-4995-bbcf-38b5fcd72479','ro','Departe de țărm, în larg, apa oceanului pare albastră intensă, deși apa în sine este incoloră. Ce explică această culoare?','["Apa reflectă mai ales radiațiile albastre din lumina solară.","Sarea dizolvată colorează apa în albastru.","Adâncimea mare face apa să pară albastră întotdeauna.","Curenții reci vopsesc apa în albastru."]','Culoarea apei este dată în primul rând de felul în care ea reflectă radiațiile din spectrul vizibil — apa curată reflectă mai ales albastrul; algele și particulele în suspensie pot schimba această culoare.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('25a09596-b301-42aa-8ee9-1d069666ab0f','9','hidrosfera','published',1,267,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('25a09596-b301-42aa-8ee9-1d069666ab0f','ro','Un cutremur submarin puternic produce un val care traversează un ocean întreg și lovește un țărm îndepărtat cu forță distrugătoare. Ce tip de val este și cum se numește popular?','["Val eolian, numit valuri de vânt.","Val seismic, numit „tsunami”.","Maree, numit flux.","Curent oceanic cald."]','Cele mai multe valuri sunt eoliene (produse de vânt), dar cele produse de cutremure submarine se numesc valuri seismice sau „tsunami” — extrem de periculoase la țărm din cauza forței lor.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('d03c44e1-1105-4257-bc54-afece82f7829','9','hidrosfera','published',1,268,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('d03c44e1-1105-4257-bc54-afece82f7829','ro','Două râuri au aceeași lățime a albiei, dar unul curge mult mai repede decât celălalt. Care mărime descrie exact această diferență de viteză de curgere?','["Debitul, măsurat în m³/s.","Viteza, adică distanța parcursă de apă în unitatea de timp.","Bazinul hidrografic.","Cumpăna apelor."]','Viteza este distanța parcursă de apa râului într-o unitate de timp; debitul, în schimb, măsoară volumul de apă scurs printr-o secțiune a albiei, indiferent de cât de repede curge acea apă.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('3bc3bfe5-84f7-4039-a33f-420cc92ea8aa','9','hidrosfera','published',1,269,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('3bc3bfe5-84f7-4039-a33f-420cc92ea8aa','ro','După ploi abundente, nivelul unui râu crește periodic și apa acoperă lunca, dar fără pagube deosebite. În altă zonă, o creștere bruscă a nivelului, provocată de topirea rapidă a zăpezii, provoacă pagube mari peste zonele învecinate. Cum numim cele două fenomene?','["Primul este o inundație, al doilea o revărsare.","Primul este o revărsare (creștere periodică), al doilea o inundație (revărsare neregulată, cu pagube), provocată de o viitură.","Ambele sunt viituri identice.","Primul este un afluent, al doilea o confluență."]','Revărsarea este creșterea periodică a nivelului, cu apa acoperind lunca; viitura este creșterea bruscă și puternică; inundația este revărsarea neregulată, cu pagube, cauzată adesea de o viitură.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('860939da-565d-4a04-b948-e9bde941c7c6','9','hidrosfera','published',1,270,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('860939da-565d-4a04-b948-e9bde941c7c6','ro','Un râu mic se varsă într-un râu mai mare, chiar în locul unde acesta din urmă își schimbă ușor direcția. Cum se numesc râul mic și, respectiv, locul unirii lor?','["Râul mic este colector, locul este izvor.","Râul mic este afluent, locul este confluență.","Râul mic este bazin hidrografic, locul este cumpăna apelor.","Râul mic este curs superior, locul este gură de vărsare."]','Afluentul este apa care se varsă într-un râu mai mare (colector); locul unde se unesc cele două ape se numește confluență.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('76161c2b-30b4-42b9-94ea-afd43e705b95','9','hidrosfera','published',1,271,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('76161c2b-30b4-42b9-94ea-afd43e705b95','ro','Lacul Baikal ocupă o adâncitură formată prin mișcări ale scoarței terestre, nu prin acțiunea apei, gheții sau vântului. Ce tip de lac este și ce agent i-a săpat cuveta?','["Lac carstic, format de agenți externi.","Lac tectonic, format de agenți interni.","Lac antropic, format de om.","Lac litoral, format de valuri."]','Lacurile tectonice, ca Baikal sau Tanganyika, ocupă cuvete create de mișcările scoarței — deci de agenți interni; se deosebesc de lacurile glaciare, carstice sau litorale, create de agenți externi.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('b9df2e6b-dea0-45cf-86e2-304c7c52ef92','9','hidrosfera','published',1,272,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('b9df2e6b-dea0-45cf-86e2-304c7c52ef92','ro','Un lac ocupă o adâncitură săpată de un fost ghețar montan, iar altul s-a format într-o zonă de calcar dizolvat de apă. Cum se numesc cele două tipuri de lac?','["Primul este lac vulcanic, al doilea lac litoral.","Primul este lac glaciar (în circuri și văi glaciare), al doilea lac carstic (în roci dizolvate).","Amândouă sunt lacuri tectonice.","Primul este iaz, al doilea heleșteu."]','Lacurile glaciare apar în circuri și văi săpate de foștii ghețari (ex. Bâlea, Bucura); lacurile carstice apar în roci solubile, dizolvate de apă (ex. Vărășoaia).');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('14eaf685-d7f9-49a2-beed-93f3aea569c6','9','hidrosfera','published',1,273,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('14eaf685-d7f9-49a2-beed-93f3aea569c6','ro','În spatele unui baraj mare, construit de om pe un râu, s-a format un lac folosit pentru producerea energiei electrice. Ce tip de lac este, după origine?','["Lac natural de baraj natural.","Lac antropic (hidroenergetic), format prin bararea artificială a unei văi.","Lac tectonic.","Lac litoral (lagună)."]','Lacurile antropice se formează în spatele barajelor construite de om; cele destinate producerii energiei electrice, ca Lacul Vidra, se numesc lacuri hidroenergetice — se deosebesc de iazuri (irigații, adăpat) și heleștee (piscicultură).');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('538414c8-4661-4c5d-a550-345d15db0868','9','hidrosfera','published',1,274,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('538414c8-4661-4c5d-a550-345d15db0868','ro','Un ghețar de pe un munte înalt are o zonă unde se acumulează zăpada și gheața, urmată de o „limbă” de gheață care coboară pe vale, cărând și depunând materiale la margini. Cum se numesc aceste elemente?','["Zona de acumulare este un fiord, iar materialele depuse sunt aisberguri.","Zona de acumulare este circul glaciar, iar materialele cărate și depuse de ghețar se numesc morene.","Zona de acumulare este banchiza, iar materialele sunt calote.","Zona de acumulare este un nevé continental, fără materiale depuse."]','Un ghețar de vale (montan) are o zonă de acumulare numită circul glaciar și o limbă care coboară pe pantă; materialele cărate și depuse de ghețar formează morenele — spre deosebire de ghețarii continentali (de calotă), care acoperă uniform Antarctida și Groenlanda.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('05b8f263-32e3-409a-838e-9d9dc8527ac8','9','climatele-terrei','published',1,281,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('05b8f263-32e3-409a-838e-9d9dc8527ac8','ro','Alizeele bat dinspre tropice spre Ecuator, iar vânturile de vest bat în zona temperată, dinspre ocean spre uscat. Ce rol joacă aceste vânturi permanente în formarea climei?','["Nu influențează deloc clima, doar temperatura aerului la sol.","Ele transportă mase de aer cald sau rece, umed sau uscat, dintr-o regiune în alta, fiind unul dintre factorii climatogeni.","Determină doar direcția curenților oceanici, fără legătură cu clima.","Apar exclusiv iarna, în emisfera nordică."]','Circulația maselor de aer și vânturile permanente (alizeele, vânturile de vest, vânturile polare, musonii) sunt unul dintre factorii climatogeni: ele aduc aer cald sau rece, umed sau uscat, modelând clima regiunilor peste care trec.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('1fdf91d7-35e2-43cc-b4e7-75a10c33baa1','9','climatele-terrei','published',0,282,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('1fdf91d7-35e2-43cc-b4e7-75a10c33baa1','ro','Un climat are veri calde și secetoase, ierni blânde și ploioase, cu vegetație de arbori și tufișuri mereu verzi. Alt climat, la latitudini apropiate, primește ploi mai ales vara, sub influența musonilor și alizeelor. Cum se numesc cele două climate?','["Primul este subtropical-mediteranean, al doilea subtropical cu ploi de vară.","Primul este temperat-oceanic, al doilea temperat-continental.","Primul este tropical-arid, al doilea musonic.","Ambele sunt climate polare."]','Climatul subtropical-mediteranean are veri calde-secetoase și ierni blânde-ploioase (păduri și tufișuri veșnic verzi); climatul subtropical cu ploi de vară, la latitudini apropiate, primește ploile mai ales vara, sub musoni și alizee.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('e4927afa-0460-4e7d-8a8a-f32293dc0e37','9','climatele-terrei','published',0,283,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('e4927afa-0460-4e7d-8a8a-f32293dc0e37','ro','Un oraș aflat aproape de țărmul oceanic are veri răcoroase, ierni blânde și ploi tot anul; alt oraș, la aceeași latitudine dar în interiorul continentului, are ierni geroase, veri calde și precipitații mai reduse, cu vegetație de stepă. Cum numim cele două climate?','["Primul este temperat-oceanic, al doilea temperat-continental-umed.","Primul este subpolar, al doilea polar.","Primul este musonic, al doilea mediteranean.","Ambele sunt climate ecuatoriale."]','Apropierea de ocean temperează clima (temperat-oceanic: ploi bogate, contraste mici); depărtarea de ocean, spre interiorul continentului, accentuează contrastele (temperat-continental-umed, cu ierni geroase și vegetație de stepă și silvostepă).');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('d090f645-d640-4ff8-88cc-cd05764ce14f','9','climatele-terrei','published',0,284,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('d090f645-d640-4ff8-88cc-cd05764ce14f','ro','Într-o regiune situată între 50° și 60° latitudine nordică, iernile sunt lungi și aspre (în jur de −10 °C), verile scurte și răcoroase, iar vegetația dominantă este pădurea de conifere veșnic verde. Ce climat și ce tip de vegetație sunt acestea?','["Climat temperat-rece (boreal), cu pădure de conifere (taiga).","Climat polar, cu tundră.","Climat subtropical, cu pădure de foioase.","Climat ecuatorial, cu pădure deasă."]','Climatul temperat-rece (boreal), la 50–60° latitudine, are ierni lungi și aspre și veri scurte; sub el se dezvoltă taigaua, pădurea de conifere, adaptată la frig.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('8f968127-a8ee-4941-8b13-2b14ad0f0a48','9','climatele-terrei','published',1,285,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('8f968127-a8ee-4941-8b13-2b14ad0f0a48','ro','În interiorul unui continent, la 40–50° latitudine, precipitațiile sunt sub 250 mm/an, iar temperatura medie anuală este de doar 5–8 °C — mult mai rece decât marile deșerturi calde. Ce climat este acesta și unde poate fi întâlnit?','["Climat tropical-arid, ca Sahara.","Climat temperat-continental-arid, ca în deșertul Gobi.","Climat subecuatorial, cu savană.","Climat polar, cu deșert de gheață."]','Climatul temperat-continental-arid apare în interiorul continentelor, la latitudini medii, cu precipitații foarte reduse dar temperaturi mult mai scăzute decât la deșerturile calde tropicale — exemplul clasic este Gobi.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('d7c3d6c3-ec30-4c82-b800-c05147f0a656','9','climatele-terrei','published',1,286,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('d7c3d6c3-ec30-4c82-b800-c05147f0a656','ro','Dincolo de cercurile polare, temperatura medie anuală este sub 10 °C, iar vegetația este formată din mușchi, licheni și arbuști pitici, lipiți de sol. Ce climat și ce zonă biogeografică sunt acestea?','["Climat polar, cu deșert de gheață.","Climat subpolar, cu vegetație de tundră.","Climat temperat-rece, cu taiga.","Climat subecuatorial, cu savană."]','Climatul subpolar (60–66°) are temperaturi medii sub 10 °C și precipitații reduse; sub el se dezvoltă tundra, cu vegetație scundă — mușchi, licheni, arbuști pitici, adaptați la frig și la sezonul de vegetație foarte scurt.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('b4efb2cb-ca52-4726-8d19-243b198533ac','9','climatele-terrei','published',2,287,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('b4efb2cb-ca52-4726-8d19-243b198533ac','ro','Dincolo de 66° latitudine, temperatura medie rămâne sub 0 °C tot anul, precipitațiile sunt foarte reduse (100–200 mm), iar suprafața este acoperită de calote de gheață aproape lipsite de vegetație. Ce climat este acesta?','["Climatul ecuatorial.","Climatul tropical-arid.","Climatul polar — un adevărat deșert rece.","Climatul temperat-oceanic."]','Climatul polar (66–90°) are temperaturi permanent negative și precipitații foarte mici, comportându-se ca un deșert — dar unul rece, acoperit de gheață, aproape lipsit de vegetație.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('8962fd5b-b44c-4f34-979c-30d915627cb5','9','climatele-terrei','published',1,288,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('8962fd5b-b44c-4f34-979c-30d915627cb5','ro','Climatul ecuatorial are precipitații de 1.000–3.000 mm/an, iar climatul tropical-arid, la latitudini apropiate de Ecuator, are doar 100–250 mm/an. Ce arată această diferență uriașă despre rolul latitudinii în cantitatea de precipitații?','["Că precipitațiile depind exclusiv de temperatură, nu de latitudine.","Că, deși ambele climate sunt calde, circulația aerului diferă mult între ele: la Ecuator aerul urcă și plouă abundent, la tropice aerul coboară uscat.","Că cele două climate au aceeași vegetație.","Că tropical-aridul se află mai aproape de poli decât ecuatorialul."]','Temperatura ridicată nu garantează precipitații bogate — contează și circulația aerului: la Ecuator aerul cald și umed urcă și se răcește, producând ploi abundente; la tropice (12–30°) aerul coboară, uscat, aducând secetă în ciuda căldurii.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('43e3795d-b07a-4037-a39a-2f57c847e755','9','climatele-terrei','published',0,289,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('43e3795d-b07a-4037-a39a-2f57c847e755','ro','Deși climatul musonic și climatul tropical-arid se află la latitudini apropiate (12–30°), unul primește ploi torențiale vara, iar celălalt este aproape complet lipsit de precipitații. Ce explică diferența?','["Musonii sunt vânturi care își schimbă sensul cu anotimpul, aducând vara umezeală de la ocean; alizeele, care domină climatul arid, bat constant dinspre uscat.","Climatul musonic este mai aproape de Ecuator decât cel arid.","Climatul tropical-arid are altitudine mult mai mare.","Nu există nicio diferență reală între cele două climate."]','Musonii schimbă direcția cu anotimpul — vara bat dinspre ocean și aduc ploi uriașe, iarna dinspre uscat și aduc secetă. Alizeele, care domină climatul tropical-arid, bat constant dinspre uscat, fără să aducă umezeală.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('d4411799-ea39-42ca-a165-82157daae007','9','climatele-terrei','published',2,290,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('d4411799-ea39-42ca-a165-82157daae007','ro','Doi munți se află la aceeași latitudine, dar unul are, la aceeași altitudine, temperaturi mai scăzute decât zona înconjurătoare. Ce factor climatogen explică acest lucru?','["Latitudinea, care este identică pentru ambii munți.","Curenții oceanici, care nu ajung la munte.","Relieful și altitudinea — cu cât urcăm mai sus, cu atât temperatura scade.","Vânturile permanente, care nu bat niciodată la munte."]','Relieful și altitudinea sunt factori climatogeni de sine stătători: indiferent de latitudine, temperatura scade pe măsură ce urcăm, ceea ce explică de ce la munte este mai frig decât la poalele lui.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('fbe5f4b0-5e2f-4d2f-96af-eef78cbb4f9a','9','climatele-terrei','published',0,291,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('fbe5f4b0-5e2f-4d2f-96af-eef78cbb4f9a','ro','Zona temperată cuprinde șase tipuri de climă diferite (mediteranean, cu ploi de vară, oceanic, continental-umed, boreal, continental-arid), în timp ce zona caldă are doar patru. Ce explică această varietate mai mare în zona temperată?','["Zona temperată se întinde pe un interval mult mai larg de latitudini și resimte puternic influența vânturilor de vest, a apropierii sau depărtării de ocean și a altitudinii.","Zona temperată primește mai multă energie solară decât zona caldă.","În zona temperată nu bate niciun vânt permanent.","Zona caldă are mai multe continente decât zona temperată."]','Zona temperată se întinde între tropice și cercurile polare, pe un interval larg de latitudini, unde se combină diferit apropierea de ocean, vânturile de vest și altitudinea — de aici cea mai mare varietate de climate dintre cele trei zone.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('092b389f-fdb2-4948-b6db-e0f4fbd4b670','9','climatele-terrei','published',0,292,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('092b389f-fdb2-4948-b6db-e0f4fbd4b670','ro','Climatul ecuatorial are un singur anotimp (cald-ploios tot anul), pe când climatul temperat-continental-umed are patru anotimpuri bine distincte. Ce cauzează această deosebire?','["La Ecuator razele solare cad aproape drept tot anul, fără variație mare; la latitudini medii, înălțimea Soarelui pe cer variază mult de-a lungul anului, producând anotimpuri.","La Ecuator nu există deloc Soare iarna.","Climatul temperat-continental-umed nu are legătură cu mișcarea de revoluție a Pământului.","Ambele climate au exact aceleași anotimpuri, doar denumite diferit."]','La Ecuator, unghiul razelor solare rămâne aproape constant tot anul (un singur anotimp); la latitudini medii, înălțimea Soarelui variază mult între vară și iarnă, din cauza înclinării axei Pământului, ceea ce produce cele patru anotimpuri.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('fb474a61-7bb7-4824-9445-cc500cfbae50','9','climatele-terrei','published',1,293,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('fb474a61-7bb7-4824-9445-cc500cfbae50','ro','Vânturile polare, reci și uscate, domină zona rece a globului, în timp ce musonii se resimt mai ales în zona caldă, la latitudini de 12–30°. Ce arată acest lucru despre legătura dintre vânturile permanente și zonele climatice?','["Fiecare vânt permanent bate la fel de puternic peste tot globul.","Diferite vânturi permanente domină zone climatice diferite, contribuind la deosebirile dintre ele.","Musonii și vânturile polare sunt de fapt același fenomen.","Vânturile nu au nicio legătură cu zonele climatice."]','Circulația aerului diferă de la o zonă climatică la alta: alizeele și musonii domină zona caldă, vânturile de vest zona temperată, iar vânturile polare, reci și uscate, domină zona rece — fiecare contribuind la trăsăturile climatului local.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('a6574343-5a71-4d8d-bc32-8cd151e2b388','9','climatele-terrei','published',1,294,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('a6574343-5a71-4d8d-bc32-8cd151e2b388','ro','La aceeași latitudine sudică (de exemplu 45° S), un loc are un climat foarte asemănător cu cel de la 45° N, dar cu anotimpurile inversate. Ce principiu al zonalității climatice explică această asemănare?','["Cele două emisfere primesc cantități diferite de energie solară.","Simetria climatică: de la Ecuator spre fiecare pol, temperatura scade treptat și similar, astfel încât fâșiile climatice se repetă simetric în cele două emisfere.","Emisfera sudică nu are climate temperate.","Latitudinea nu influențează clima în emisfera sudică."]','Fiindcă factorul principal — cantitatea de căldură primită — scade simetric de la Ecuator spre fiecare pol, tipurile de climă se succed în fâșii asemănătoare în ambele emisfere, doar cu anotimpurile inversate.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('2b61a73d-8a08-479c-a0b8-e89daea65d08','9','solurile-terrei','published',0,301,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('2b61a73d-8a08-479c-a0b8-e89daea65d08','ro','Două soluri s-au format pe roci-mamă diferite: unul pe calcar, altul pe granit. Deși clima este identică, cele două soluri au proprietăți chimice diferite. Ce factor pedogenetic explică această deosebire?','["Roca-mamă (materialul parental), din care provine partea minerală a solului.","Timpul, care este identic pentru ambele soluri.","Omul, prin agricultură.","Relieful, care nu influențează compoziția chimică."]','Roca-mamă este factorul pedogenetic care dă partea minerală a solului; pe roci diferite, chiar în aceeași climă, rezultă soluri cu compoziții chimice diferite.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('23e4b32e-7c08-46f4-8f1c-529a00a7ad19','9','solurile-terrei','published',0,302,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('23e4b32e-7c08-46f4-8f1c-529a00a7ad19','ro','Sub o pădure deasă, solul primește multă materie organică din frunze și crengi căzute, spre deosebire de un teren fără vegetație. Ce factor pedogenetic este responsabil pentru acest aport?','["Vegetația, care dă materia organică ce se transformă în humus.","Apa, care doar dizolvă substanțele.","Relieful, care hotărăște panta terenului.","Roca-mamă."]','Vegetația este factorul pedogenetic care furnizează materia organică (frunze, rădăcini, resturi vegetale); prin descompunere, aceasta devine humus, hrănind solul.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('6c3f94c2-1aa0-43a7-a638-9962b8c60e9c','9','solurile-terrei','published',1,303,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('6c3f94c2-1aa0-43a7-a638-9962b8c60e9c','ro','La suprafața unui profil de sol se află un strat subțire, de culoare închisă, format din frunze și crengi în diferite stadii de descompunere. Sub el se află un orizont mai gros, unde humusul se amestecă intens cu partea minerală. Cum se numesc cele două orizonturi?','["Primul este orizontul E, al doilea orizontul B.","Primul este orizontul O (litiera), al doilea orizontul A (bioacumulativ).","Primul este orizontul C, al doilea orizontul R.","Primul este orizontul B, al doilea orizontul O."]','Orizontul O (litiera) este stratul de suprafață din frunze și crengi în descompunere; sub el, orizontul A este cel bioacumulativ, unde humusul se amestecă cu partea minerală — solul vegetal propriu-zis.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('fd98ad43-527e-4de0-be0b-27cce5fd7155','9','solurile-terrei','published',0,304,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('fd98ad43-527e-4de0-be0b-27cce5fd7155','ro','La baza unui profil de sol, sub toate orizonturile formate, se află roca slab consolidată, puțin atinsă de procesele de formare a solului, iar sub ea, roca dură, neafectată. Cum se numesc aceste două straturi?','["Materialul parental (orizontul C) și roca parentală compactă (orizontul R).","Orizontul A și orizontul E.","Orizontul gleic și orizontul turbos.","Orizontul B și orizontul O."]','Orizontul C este materialul parental, roca-mamă slab consolidată; sub el, orizontul R este roca parentală compactă (nealterată), baza întregului profil de sol.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('8ac2be87-fbe1-413d-a530-eda242a309ea','9','solurile-terrei','published',1,305,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('8ac2be87-fbe1-413d-a530-eda242a309ea','ro','Într-o zonă joasă, unde apa băltește permanent și oxigenul lipsește aproape complet, apare un orizont de sol cu proprietăți speciale, diferit de orizonturile obișnuite. Cum se numește acest orizont?','["Orizontul turbos.","Orizontul gleic (G).","Orizontul eluvial (E).","Orizontul iluvial (B)."]','Orizontul gleic (G) se formează acolo unde apa băltește și nu mai există oxigen — o condiție specială, diferită de orizonturile obișnuite ale unui profil de sol bine drenat.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('e97a8b73-27c5-419f-95d6-87bfddf376a2','9','solurile-terrei','published',0,306,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('e97a8b73-27c5-419f-95d6-87bfddf376a2','ro','Într-o zonă rece și foarte umedă, resturile vegetale nu apucă să se descompună complet și se acumulează într-un strat gros, specific. Ce orizont de sol este acesta?','["Orizontul turbos, din resturi vegetale slab descompuse, în locuri reci și umede.","Orizontul C, materialul parental.","Orizontul A, bioacumulativ obișnuit.","Orizontul R, roca parentală."]','Orizontul turbos apare acolo unde umiditatea mare și temperaturile scăzute încetinesc descompunerea, iar resturile vegetale se acumulează slab descompuse, într-un strat gros și specific.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('f2807874-db51-4ce5-8a21-88c40382af47','9','solurile-terrei','published',1,307,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('f2807874-db51-4ce5-8a21-88c40382af47','ro','Un sol este descris astfel: „particulele lui se leagă în agregate de formă grăunțoasă”. Un alt sol este descris prin mărimea particulelor: „predomină granulele fine, sub 0,002 mm”. La ce proprietăți diferite ale solului se referă cele două descrieri?','["Ambele descrieri se referă la structură.","Prima descriere se referă la structură (felul în care se leagă particulele), a doua la textură (mărimea particulelor).","Prima se referă la fertilitate, a doua la culoare.","Ambele descrieri se referă la textură."]','Structura este felul în care particulele solului se leagă în agregate (de exemplu grăunțoasă); textura este dată de mărimea particulelor (nisip, praf, argilă) — două proprietăți diferite, ușor de confundat.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('2273be24-5730-45cb-aa2e-a45dd21aadf2','9','solurile-terrei','published',1,308,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('2273be24-5730-45cb-aa2e-a45dd21aadf2','ro','Doi agronomi testează un sol: unul verifică dacă solul este acid, neutru sau bazic, celălalt verifică cât de repede se scurge apa prin el. Ce proprietăți ale solului măsoară fiecare?','["Primul măsoară fertilitatea, al doilea culoarea.","Primul măsoară pH-ul (reacția chimică), al doilea permeabilitatea.","Amândoi măsoară aceeași proprietate: textura.","Primul măsoară structura, al doilea porozitatea."]','pH-ul (reacția chimică) arată dacă solul este acid, neutru sau bazic; permeabilitatea arată cât de ușor lasă solul apa să treacă — două proprietăți distincte ale solului, ambele importante pentru agricultură.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('16afe5ef-2929-4e46-b12f-579d0116c2f9','9','solurile-terrei','published',1,309,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('16afe5ef-2929-4e46-b12f-579d0116c2f9','ro','Un sol matur, cu toate orizonturile bine dezvoltate, s-a format într-o zonă stabilă de-a lungul a mii de ani. Într-o zonă vecină, afectată recent de o alunecare de teren, solul este subțire și slab dezvoltat. Ce factor pedogenetic explică diferența?','["Clima, care este identică în cele două zone.","Timpul — solurile mature se formează în mii de ani, iar o suprafață recent expusă nu a avut încă timp să dezvolte un profil complet.","Roca-mamă, care nu influențează viteza de formare.","Vegetația, care este identică în cele două zone."]','Timpul este factorul pedogenetic care hotărăște gradul de maturitate al unui sol: solurile mature, cu orizonturi bine dezvoltate, cer mii de ani; o suprafață recent expusă (de exemplu după o alunecare) rămâne cu un sol subțire, tânăr.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('9d1151f9-03d0-4e00-8879-79ad76a6326e','9','solurile-terrei','published',0,310,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('9d1151f9-03d0-4e00-8879-79ad76a6326e','ro','Într-o regiune, agricultura intensivă și fertilizarea excesivă au schimbat de-a lungul timpului proprietățile chimice ale solului, față de starea lui naturală. Ce factor pedogenetic este responsabil pentru această schimbare?','["Omul, care prin agricultură poate îmbunătăți sau distruge solul.","Relieful, care rămâne neschimbat de activitatea umană.","Timpul, singurul factor implicat.","Apa freatică, singurul factor implicat."]','Omul este el însuși un factor pedogenetic: prin agricultură, irigații sau fertilizare, poate îmbunătăți solul, dar îl poate și degrada (eroziune, sărăturare, epuizarea nutrienților).');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('c068bdd8-320e-4cc7-b1ba-81bed2600285','9','solurile-terrei','published',1,311,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('c068bdd8-320e-4cc7-b1ba-81bed2600285','ro','Un fermier alege un teren pentru cultură nu după culoare sau textură, ci după cât de bine hrănește acesta plantele. Ce proprietate a solului urmărește el, de fapt, în primul rând?','["Structura.","Fertilitatea — capacitatea solului de a hrăni plantele, cea mai importantă proprietate a lui.","Porozitatea.","pH-ul."]','Fertilitatea este însușirea de bază a solului — capacitatea lui de a hrăni plantele; toate celelalte proprietăți (textură, structură, pH etc.) contează, până la urmă, pentru cât de fertil este solul.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('724beafd-3c1a-4901-8617-5321792b5fbb','9','solurile-terrei','published',2,312,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('724beafd-3c1a-4901-8617-5321792b5fbb','ro','Sub o pădure de foioase, dintr-o climă temperată, se formează un sol numit argiluvisol; sub o pădure de conifere, într-o climă mai rece și umedă, se formează un spodosol. Ambele rezultă din același proces pedogenetic, dar cu intensități diferite. Care este acest proces?','["Calcifierea.","Lateritizarea.","Podzolirea — spălarea argilei, humusului și compușilor de fier și aluminiu din orizontul superior spre unul inferior.","Salinizarea."]','Ambele soluri rezultă din podzolire, dar cu intensitate diferită: sub conifere, în climă mai rece și mai umedă, spălarea este mai puternică și rezultă spodosolul; sub foioase, mai temperat, rezultă argiluvisolul (alfisolul), mai puțin spălat.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('d49d15dc-9214-490a-a74b-1b1f98eecd09','9','solurile-terrei','published',0,313,1784000000000,1784000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('d49d15dc-9214-490a-a74b-1b1f98eecd09','ro','Sub vegetația de stepă se formează cel mai fertil sol de pe glob (molisolul/cernoziomul), în timp ce în deșert se formează un sol sărac, cu carbonați acumulați (aridisolul). Ambele rezultă din calcifiere, dar cu rezultate opuse în privința fertilității. Ce explică deosebirea?','["În stepă, ierburile lasă mult humus care se acumulează într-un orizont gros, pe când în deșert vegetația este rară și materia organică aproape lipsește.","În deșert plouă mai mult decât în stepă.","Cernoziomul se formează doar prin lateritizare.","Aridisolul are mai mult humus decât cernoziomul."]','Deși ambele procese sunt calcifieri (climă secetoasă, apa nu spală în adânc), stepa are vegetație bogată de ierburi care lasă mult humus — de aici fertilitatea record a cernoziomului; deșertul are vegetație foarte rară, deci humus puțin și fertilitate scăzută, în ciuda acumulării de carbonați.');
